/* ULTERA Aganta Oreo: eight-view rotation, original photograph at 0°. */
(()=>{'use strict';
const wrap=document.getElementById('m_img_wrap'),photo=document.getElementById('m_img'),title=document.getElementById('m_title');if(!wrap||!photo||!title)return;
const style=document.createElement('style');style.textContent='#aganta360Toggle{position:absolute;left:50%;bottom:68px;transform:translateX(-50%);z-index:55;border:0;border-radius:24px;padding:12px 20px;background:#caff00;color:#151515;font:700 12px/1.2 Arial,sans-serif;letter-spacing:.5px;white-space:nowrap;cursor:pointer;box-shadow:0 3px 14px #0002}#aganta360Toggle[hidden],#aganta360Canvas[hidden]{display:none!important}#aganta360Canvas{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none;z-index:4}';document.head.appendChild(style);
const btn=document.createElement('button');btn.id='aganta360Toggle';btn.type='button';btn.textContent='↻ Обернути 360°';btn.setAttribute('aria-pressed','false');btn.hidden=true;wrap.appendChild(btn);
const canvas=document.createElement('canvas');canvas.id='aganta360Canvas';canvas.width=900;canvas.height=1125;canvas.hidden=true;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Огляд Aganta Oreo на 360 градусів, реконструйований за фотографіями');wrap.appendChild(canvas);const ctx=canvas.getContext('2d');
let running=false,raf=0,last=0,angle=0,atlas=null,loading=null,frames=[],savedVisibility='';
function eligible(){return wrap.dataset.fam==='Aganta'&&/OREO/i.test(title.textContent)}
function stop(){running=false;cancelAnimationFrame(raf);raf=0;last=0;angle=0;canvas.hidden=true;photo.style.visibility=savedVisibility;btn.setAttribute('aria-pressed','false');btn.textContent='↻ Обернути 360°'}
function sync(){const ok=eligible();btn.hidden=!ok;if(!ok)stop()}
function load(){if(loading)return loading;loading=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{atlas=im;const w=im.width/4,h=im.height/2;for(let i=0;i<8;i++){const tmp=document.createElement('canvas');tmp.width=Math.round(w);tmp.height=Math.round(h);const t=tmp.getContext('2d',{willReadFrequently:true});t.drawImage(im,(i%4)*w,Math.floor(i/4)*h,w,h,0,0,tmp.width,tmp.height);const d=t.getImageData(0,0,tmp.width,tmp.height).data;let left=tmp.width,right=0,bottom=0;for(let y=0;y<tmp.height;y++)for(let x=0;x<tmp.width;x++){let k=(y*tmp.width+x)*4;if(d[k]<110&&d[k+1]<110&&d[k+2]<110){left=Math.min(left,x);right=Math.max(right,x);bottom=Math.max(bottom,y)}}frames.push({left,right,bottom})}resolve()};im.onerror=()=>{loading=null;reject(new Error('Aganta Oreo rotation asset unavailable'))};im.src='data:image/webp;base64,'});return loading}
function render(i){if(i===0){canvas.hidden=true;photo.style.visibility=savedVisibility;return}const w=atlas.width/4,h=atlas.height/2,f=frames[i],scale=790/(w*.92);ctx.fillStyle='#efefed';ctx.fillRect(0,0,900,1125);ctx.drawImage(atlas,(i%4)*w+4,Math.floor(i/4)*h+4,w-8,h-8,450-((f.left+f.right)/2-4)*scale,880-(f.bottom-4)*scale,(w-8)*scale,(h-8)*scale);photo.style.visibility='hidden';canvas.hidden=false;canvas.dataset.frame=String(i)}
function tick(t){if(!running)return;if(last)angle=(angle+Math.min(t-last,60)*.035)%360;last=t;render(Math.round(angle/45)%8);raf=requestAnimationFrame(tick)}
btn.addEventListener('click',async e=>{e.preventDefault();e.stopPropagation();if(running){stop();return}if(!eligible())return;btn.disabled=true;try{if(typeof window.setModalPhoto==='function')window.setModalPhoto(0);await load();if(!eligible())return;savedVisibility=photo.style.visibility;running=true;angle=0;last=0;btn.setAttribute('aria-pressed','true');raf=requestAnimationFrame(tick)}catch{btn.textContent='Повторити 360°'}finally{btn.disabled=false}});
new MutationObserver(()=>{stop();sync()}).observe(photo,{attributes:true,attributeFilter:['src']});new MutationObserver(sync).observe(title,{childList:true,subtree:true,characterData:true});new MutationObserver(sync).observe(wrap,{attributes:true,attributeFilter:['data-fam']});
wrap.addEventListener('click',e=>{if(e.target!==btn&&!btn.contains(e.target))stop()},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});document.addEventListener('keydown',e=>{if(e.key==='Escape')stop()});const modal=document.getElementById('modal')||wrap.parentElement;new MutationObserver(()=>{if(!wrap.getClientRects().length)stop()}).observe(modal,{attributes:true,attributeFilter:['class','style','aria-hidden']});sync();
})();
